def is_in_S(n):
    if n < 2: return False
    if n % 4 == 0: return False
    d = n
    if d % 2 == 0:
        d //= 2
    if d % 2 == 0: # Should not happen because n%4 != 0
        return False
    i = 3
    while i * i <= d:
        if d % i == 0:
            if i % 4 == 3:
                return False
            while d % i == 0:
                d //= i
        i += 2
    if d % 4 == 3:
        return False
    return True

