def solve():
    # Since the search up to 1000 didn't work, let's try a different approach.
    # The condition is y_{i-1} y_{i+1} = (y_i-1)^2 + 1.
    # Let's try to see if there's any y1, y2, y3, y4, y5.
    # We can iterate y1 and y3, and then y2 must satisfy (y_2-1)^2 = y1 y_3 - 1.
    # This means y1 y_3 - 1 must be a perfect square.
    # Let y1 y_3 - 1 = z_2^2, then y2 = z_2 + 1.
    # Then y2 y_4 = (y_3-1)^2 + 1, so y4 = ((y_3-1)^2 + 1) / y2.
    # Then y3 y_5 = (y_4-1)^2 + 1, so y5 = ((y_4-1)^2 + 1) / y3.
    # We need y1, y2, y3, y4, y5 to be integers >= 2.
    # Since y1 y_3 - 1 = z_2^2, if we pick y1 and y3, y2 is determined.
    # This is much faster!

    for y1 in range(2, 10000):
        for y3 in range(2, 10000):
            val = y1 * y3 - 1
            z2 = int(val**0.5)
            if z2 * z2 == val:
                y2 = z2 + 1
                if y2 >= 2:
                    y4_num = (y3-1)**2 + 1
                    if y4_num % y2 == 0:
                        y4 = y4_num // y2
                        if y4 >= 2:
                            y5_num = (y4-1)**2 + 1
                            if y5_num % y3 == 0:
                                y5 = y5_num // y3
                                if y5 >= 2:
                                    print(f"Found: y1={y1}, y2={y2}, y3={y3}, y4={y4}, y5={y5}")
    return

solve()
